output_text:
[
  {
    "id": "must_take_cart_first",
    "text": "A shopper must collect the available entrance cart before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_item_without_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently pushing a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Items must be placed into the cart rather than carried by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "pushing_cart": "hasCart"
      },
      "events": {
        "pickup_into_hand": {
          "pre": "PICKUP_ITEM",
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_into_hand"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking a cart, the shopper must return it to the designated cart bay at cell (0,1) before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_bay": "at(0,1)",
        "cart_parked_in_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "cart_bay"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_cart_abandonment_elsewhere",
    "text": "A shopper is prohibited from leaving the cart anywhere except the designated bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_bay": "at(0,1)",
        "outside_cart_bay": {
          "not": "at_cart_bay"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_south_while_pushing_cart",
    "text": "A shopper may not move south while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "cart_moves_south": {
          "pre": {
            "and": [
              "S",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_moves_south"
    }
  },
  {
    "id": "return_to_entrance_after_cart_drop",
    "text": "After returning the cart at the bay, the shopper must pass back through the entrance cell before exiting.",
    "abstraction": {
      "state_properties": {
        "entrance_cell": "at(0,5)",
        "cart_bay_cell": "at(0,1)",
        "cart_parked_in_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_returned": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "cart_bay_cell"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_returned",
      "discharge": "entrance_cell"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "A shopper is prohibited from exiting unless they are no longer pushing the cart and the cart is parked in the bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "not_pushing_cart": {
          "not": "hasCart"
        },
        "cart_parked_in_bay": "cartAt(0,1)",
        "ready_to_exit": {
          "and": [
            "not_pushing_cart",
            "cart_parked_in_bay"
          ]
        }
      },
      "events": {
        "improper_exit": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "ready_to_exit"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_exit"
    }
  }
]
